}

Method.Source:
/// <summary>
/// avaNewTypeAndRestrictAndNotePositionSortDesc additionally to KCS_TCV logic sorts by SortDesc descending order
/// </summary>
/// <param name="_common">
/// Common
/// </param>
/// <param name="_docuTypeId">
/// DocuTypeId
/// </param>
/// <param name="_restriction">
/// DocuRestriction
/// </param>
/// <param name="_notePosition">
/// KCS_TCVNotePosition
/// </param>
/// <param name="_date">
/// date
/// </param>
/// <returns>
/// docuRefSearch
/// </returns>
static DocuRefSearch avaNewTypeAndRestrictAndNotePositionSortDesc(
    Common              _common,
    DocuTypeId          _docuTypeId,
    DocuRestriction     _restriction,
    AVATCVNotePosition _notePosition,
    date                _date = dateNull())
{

    AVADocuRefSearch_Derived docuRefSearch = new AVADocuRefSearch_Derived();

    docuRefSearch.parmCommon(_common);
    docuRefSearch.parmDocuTypeId(_docuTypeId);
    docuRefSearch.parmAllRestrictions(false);
    docuRefSearch.KCS_TCVParmAllPaperTypes(true);
    docuRefSearch.KCS_TCVParmNoSpecificPosition(false);
    docuRefSearch.parmRestriction(_restriction);
    docuRefSearch.AVATCVparmNotePosition(_notePosition);
    docuRefSearch.KCS_TCVParmDate(_date);
    docuRefSearch.init();

    return docuRefSearch;
}
